import requests


def test_connection() -> dict:
    response = requests.get(
        f"{ctx.var('api_base')}/health",
        headers={"Authorization": f"Bearer {ctx.secret('api_token')}"},
        timeout=10,
    )
    if response.ok:
        return {"status": "SUCCESS", "message": "API reachable."}
    return {"status": "FAILURE", "message": f"HTTP {response.status_code}"}

def test_connection() -> dict:
    """Nothing to reach: this connector reads files it is given."""
    return {"status": "SUCCESS", "message": f"{len(ctx.files)} file(s) available."}

def extract_large_file():
    """Not part of the contract -- an alternative for a payload too big to hold.

    `pages()` yields rows for a tabular file and lines for anything else, so a
    multi-gigabyte dump becomes many assets and is never in memory at once.
    """
    for file in ctx.files:
        for index, page in enumerate(pages(file, page_size=500)):
            if ctx.should_abort:
                return
            yield Asset(
                id=f"{file.name}#{index}",
                name=f"{file.name} (page {index + 1})",
                kind="table",
                content=page,
            )

def test_connection() -> dict:
    if not ctx.files:
        return {
            "status": "FAILURE",
            "message": "No files uploaded to this source yet.",
        }
    names = ", ".join(file.name for file in ctx.files[:5])
    return {"status": "SUCCESS", "message": f"{len(ctx.files)} file(s): {names}"}

def extract():
    for file in ctx.files:
        if ctx.should_abort:
            return
        yield Asset(
            id=file.name,
            name=file.name,
            kind="file",
            content=file.parse().text,
            content_bytes=file.read_bytes(),
            metadata={"size_bytes": file.size_bytes},
        )

def test_connection() -> dict:
    try:
        root = ctx.folder("dumps")
    except KeyError as exc:
        return {"status": "FAILURE", "message": str(exc)}
    if not root.is_dir():
        return {"status": "FAILURE", "message": f"{root} is not a directory."}
    return {"status": "SUCCESS", "message": f"Reading {root}."}
